-- Border colors are generated by matugen from the current wallpaper
-- (see ~/.config/matugen/templates/hyprland-colors.lua). Fall back to the
-- old defaults if matugen has not generated the palette yet.
local ok, colors = pcall(require, "hyprcolors")
if not ok or type(colors) ~= "table" or not colors.active_border then
    colors = {
        active_border     = "rgba(33ccffee)",
        active_border_alt = "rgba(00ff99ee)",
        inactive_border   = "rgba(595959aa)",
    }
end

